using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Shared fixture that boots the Aspire AppHost and exposes the chat client for evaluations.
/// </summary>
public sealed class AppHostFixture : IAsyncDisposable
{
    private DistributedApplication? _app;

    public IChatClient ChatClient { get; private set; } = null!;

    public async Task StartAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        var chatClientService = _app.Services.GetRequiredService<IChatClient>();
        ChatClient = chatClientService;
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Configures the evaluation reporting pipeline and quality metrics.
/// </summary>
public static class EvaluationFixture
{
    private static readonly string ReportPath =
        Path.Combine(Path.GetDirectoryName(typeof(EvaluationFixture).Assembly.Location)!, "eval-reports");

    public static ReportingConfiguration CreateReportingConfiguration()
    {
        var storage = new DiskBasedReportingStorage(ReportPath);

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(storage, evaluators);
    }
}

