using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using MyApp.Evaluation.Infrastructure;

namespace MyApp.Evaluation.Scenarios;

[TestClass]
public sealed class ChatQualityTests
{
    private static AppHostFixture _fixture = null!;
    private static ReportingConfiguration _reporting = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext _)
    {
        _fixture = new AppHostFixture();
        await _fixture.StartAsync();
        _reporting = EvaluationFixture.CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _fixture.DisposeAsync();
    }

    [TestMethod]
    public async Task GreetingResponse_IsRelevantAndCoherent()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, can you help me?")
        };

        // Act
        var response = await _fixture.ChatClient.GetResponseAsync(messages);

        // Evaluate
        await using var scenarioRun = await _reporting.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingResponse_IsRelevantAndCoherent));

        var result = await scenarioRun.EvaluateAsync(
            messages,
            response);

        Assert.IsFalse(result.ContainsDiagnostics(d => d.Severity == EvaluationDiagnosticSeverity.Error));
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndFluent()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _fixture.ChatClient.GetResponseAsync(messages);

        // Evaluate
        await using var scenarioRun = await _reporting.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsGroundedAndFluent));

        var result = await scenarioRun.EvaluateAsync(
            messages,
            response);

        Assert.IsFalse(result.ContainsDiagnostics(d => d.Severity == EvaluationDiagnosticSeverity.Error));
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan."),
            new(ChatRole.Assistant, "That sounds exciting! When are you planning to go?"),
            new(ChatRole.User, "Next spring. What should I pack?")
        };

        // Act
        var response = await _fixture.ChatClient.GetResponseAsync(messages);

        // Evaluate
        await using var scenarioRun = await _reporting.CreateScenarioRunAsync(
            scenarioName: nameof(MultiTurnConversation_MaintainsCoherence));

        var result = await scenarioRun.EvaluateAsync(
            messages,
            response);

        Assert.IsFalse(result.ContainsDiagnostics(d => d.Severity == EvaluationDiagnosticSeverity.Error));
    }
}

