    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _fixture.DisposeAsync();
    }

    [TestMethod]
    public async Task GreetingResponse_IsRelevantAndCoherent()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, can you help me?")
        };

        // Act
        var response = await _fixture.ChatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        // Evaluate
        await using var session = await _reporting.CreateSessionAsync(
